package br.com.nuvemtv;
import org.junit.*;import org.json.*;import java.util.*;import static org.junit.Assert.*;
public class SocialApiTest {
 static class Http implements SocialApi.Transport{String method,url,contract;JSONObject body;boolean reject;public JSONObject call(String m,String u,String c,JSONObject b)throws Exception{method=m;url=u;contract=c;body=b;if(reject)throw new java.io.IOException("HTTP 403");return Json.obj("people",Json.arr(Json.obj("xuid","123","gamertag","Test")));}}
 @Test public void searchEscapesUserInputAndReadsOnlyValidIds()throws Exception{Http h=new Http();SocialApi api=new SocialApi(h);assertEquals(1,api.search("a b&c").length());assertTrue(h.url.contains("q=a%20b%26c"));assertEquals("GET",h.method);JSONArray result=SocialApi.people(Json.obj("people",Json.arr(Json.obj("xuid","123"),Json.obj("xuid","123"),Json.obj("xuid","bad"))));assertEquals(1,result.length());}
 @Test public void friendRequestIsDifferentFromFollowing()throws Exception{Http h=new Http();SocialApi api=new SocialApi(h);api.requestFriend("123");assertEquals("POST",h.method);assertTrue(h.url.contains("friends/v2?method=add"));assertEquals("123",h.body.getJSONArray("xuids").getString(0));api.follow("123");assertEquals("PUT",h.method);assertTrue(h.url.endsWith("people/xuid(123)"));}
 @Test public void messageSerializesActualContentAndRejectsLongText()throws Exception{Http h=new Http();SocialApi api=new SocialApi(h);api.message("123"," Olá \"amigo\" ");assertEquals("POST",h.method);assertEquals("Olá \"amigo\"",h.body.getJSONArray("parts").getJSONObject(0).getString("text"));try{api.message("123",String.join("",Collections.nCopies(257,"a")));fail();}catch(IllegalArgumentException expected){}}
 @Test public void serverErrorsDoNotBecomeSuccess()throws Exception{Http h=new Http();h.reject=true;try{new SocialApi(h).requestFriend("123");fail();}catch(java.io.IOException expected){}}
 @Test public void targetCannotInjectAUrl()throws Exception{Http h=new Http();try{new SocialApi(h).follow("123)/other");fail();}catch(IllegalArgumentException expected){}assertNull(h.method);}
 @Test public void search400TriesCompatibleDecorationThenExactProfileWithPicture()throws Exception{java.util.List<String> urls=new java.util.ArrayList<>();SocialApi api=new SocialApi((method,url,contract,body)->{urls.add(url);if(url.contains("peoplehub"))throw new Net.HttpError(400,"BadRequest");return Json.obj("profileUsers",Json.arr(Json.obj("id","123","settings",Json.arr(Json.obj("id","Gamertag","value","Nome#1234"),Json.obj("id","GameDisplayPicRaw","value","https://avatar-ssl.xboxlive.com/photo.png")))));});JSONArray result=api.search("Nome#1234");assertEquals(3,urls.size());assertFalse(urls.get(0).contains("presenceDetail"));assertTrue(urls.get(0).contains("preferredColor"));assertTrue(urls.get(1).contains("/detail?"));assertTrue(urls.get(2).contains("gt(Nome%231234)"));assertEquals("123",result.getJSONObject(0).getString("xuid"));assertTrue(result.getJSONObject(0).getString("displayPicRaw").endsWith("photo.png"));}
 @Test public void forbiddenIsNotMistakenForSearchFormatError()throws Exception{int[] calls={0};try{new SocialApi((m,u,c,b)->{calls[0]++;throw new Net.HttpError(403,"denied");}).search("name");fail();}catch(Net.HttpError expected){assertEquals(1,calls[0]);}}
 @Test public void messagePaginationEncodesOpaqueCursorAndFollowErrorIsNotSuccess()throws Exception{Http h=new Http();new SocialApi(h).conversation("123","page/a+b=");assertTrue(h.url.contains("continuationToken=page%2Fa%2Bb%3D"));try{new SocialApi((m,u,c,b)->Json.obj("error","denied")).follow("123");fail();}catch(Exception expected){assertTrue(expected.getMessage().contains("recusou"));}}
}
